<?php
declare(strict_types=1);
// Page: ?page=view — included by index.php inside its try/catch, after the sign-in, CSRF and $page checks.
 require_perm('view_tables'); $schema=current_schema(); $table=$_GET['table']??''; $r=fetch_record($schema,$table,$_GET); if(!$r) throw new RuntimeException('Record not found'); $display=redact_row($r); layout_start('Record Details'); ?><div class="cardx"><div class="d-flex justify-content-between"><h3><?=e($table)?> Record</h3><div class="d-flex gap-2"><a class="btn btn-warning" href="?page=form&mode=edit&table=<?=urlencode($table)?>&<?=row_key_query($schema,$table,$r)?>">Edit</a><a class="btn btn-success" href="?page=form&mode=duplicate&table=<?=urlencode($table)?>&<?=row_key_query($schema,$table,$r)?>">Duplicate</a><a class="btn btn-outline-dark" href="?page=copy_record&table=<?=urlencode($table)?>&<?=row_key_query($schema,$table,$r)?>">Copy to <?=e(opposite_schema($schema))?></a></div></div><div class="detail-grid mt-3"><?php foreach($display as $k=>$v):?><div><label><?=e($k)?></label><pre><?=e($v)?></pre></div><?php endforeach;?></div><div class="alert alert-secondary mt-3">Delete is disabled by system policy. Use status fields such as disabled/retired/deleted_at where available.</div></div><?php layout_end(); exit;
